class Solution {
  public boolean[] subsequenceSumAfterCapping(int[] nums, int k) {
    int n = nums.length;
    int[] count = new int[n + 2];
    for (int v : nums) count[v]++;
    boolean[] dp = new boolean[k + 1];
    dp[0] = true;
    boolean[] ans = new boolean[n];
    int below = 0;
    for (int x = 1; x <= n; x++) {
      int atLeast = n - below;
      for (int t = 0; t <= atLeast && (long) t * x <= k; t++) {
        if (dp[k - t * x]) {
          ans[x - 1] = true;
          break;
        }
      }
      for (int c = 0; c < count[x]; c++) {
        for (int s = k; s >= x; s--) if (dp[s - x]) dp[s] = true;
      }
      below += count[x];
    }
    return ans;
  }
}
